  ];

  let currentSlideIndex = 0;
  let currentBaseFontSize = 22; // px
  let isDarkTheme = true;

  function initPresentation() {
    const select = document.getElementById("slideSelect");
    select.innerHTML = "";
    SLIDES.forEach((slide, idx) => {
      const opt = document.createElement("option");
      opt.value = idx;
      opt.textContent = `${idx + 1}. ${slide.badge} - ${slide.title}`;
      select.appendChild(opt);
    });
    document.getElementById("totalSlidesNum").textContent = SLIDES.length;
  }

  function renderSlide(index) {
    if (index < 0) index = 0;
    if (index >= SLIDES.length) index = SLIDES.length - 1;
    currentSlideIndex = index;

    const slide = SLIDES[index];
    const card = document.getElementById("presCard");
    card.style.setProperty("--pres-font-size", currentBaseFontSize + "px");

    document.getElementById("presBadgeSection").textContent = slide.badge;
    document.getElementById("currentSlideNum").textContent = index + 1;
    document.getElementById("slideSelect").value = index;

    card.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <span class="pres-slide-tag ${slide.tag}">${slide.tagText}</span>
        <span style="font-size:0.85em; opacity:0.8; font-weight:700;">Konu ${index + 1} / ${SLIDES.length}</span>
      </div>
      <div>
        <h2>${slide.title}</h2>
        ${slide.subtitle ? `<div style="font-size:1.05em; opacity:0.85; margin-top:4px; font-weight:600;">${slide.subtitle}</div>` : ''}
      </div>
      ${slide.html}
    `;

    document.getElementById("prevBtn").disabled = (index === 0);
    document.getElementById("nextBtn").disabled = (index === SLIDES.length - 1);
  }

  function openPresentation(index) {
    initPresentation();
    renderSlide(index || 0);
    document.getElementById("presentationModal").classList.add("active");
    document.body.style.overflow = "hidden";
  }

  function closePresentation() {
    document.getElementById("presentationModal").classList.remove("active");
    document.body.style.overflow = "auto";
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(() => {});
    }
  }

  function nextSlide() {
    if (currentSlideIndex < SLIDES.length - 1) {
      renderSlide(currentSlideIndex + 1);
    }
  }

  function prevSlide() {
    if (currentSlideIndex > 0) {
      renderSlide(currentSlideIndex - 1);
    }
  }

  function jumpToSlide(idx) {
    renderSlide(parseInt(idx, 10));
  }

  function adjustFontSize(delta) {
    currentBaseFontSize = Math.max(16, Math.min(38, currentBaseFontSize + delta));
    const card = document.getElementById("presCard");
    if (card) {
      card.style.setProperty("--pres-font-size", currentBaseFontSize + "px");
    }
  }

  function togglePresentationTheme() {
    isDarkTheme = !isDarkTheme;
    const modal = document.getElementById("presentationModal");
    const btn = document.getElementById("themeToggleBtn");
    if (!isDarkTheme) {
      modal.classList.add("theme-light");
      btn.innerHTML = "🌙 Koyu Tema";
    } else {
      modal.classList.remove("theme-light");
      btn.innerHTML = "☀️ Açık Tema";
    }
  }

  function toggleNativeFullscreen() {
    try {
      if (window.parent && window.parent !== window) {
        window.parent.postMessage({ type: 'REQUEST_FULLSCREEN' }, '*');
      }
    } catch (e) {}
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => {
        document.getElementById("fsIcon").textContent = "🗗";
        document.getElementById("fsText").textContent = "Pencere";
      }).catch(err => {
        console.log("Fullscreen request failed", err);
      });
    } else {
      document.exitFullscreen().then(() => {
        document.getElementById("fsIcon").textContent = "⛶";
        document.getElementById("fsText").textContent = "Tam Ekran";
      }).catch(() => {});
    }
  }

  // Keyboard navigation
  window.addEventListener("keydown", (e) => {
    const modal = document.getElementById("presentationModal");
    if (!modal.classList.contains("active")) return;

    if (e.key === "ArrowRight" || e.key === " " || e.key === "PageDown") {
      e.preventDefault();
      nextSlide();
    } else if (e.key === "ArrowLeft" || e.key === "PageUp") {
      e.preventDefault();
      prevSlide();
    } else if (e.key === "Escape") {
      closePresentation();
    } else if (e.key === "f" || e.key === "F") {
      toggleNativeFullscreen();
    } else if (e.key === "+" || e.key === "=") {
      adjustFontSize(2);
    } else if (e.key === "-" || e.key === "_") {
      adjustFontSize(-2);
    }
  });

  // Touch Swipe for Smart Board
  let touchStartX = 0;
  let touchEndX = 0;
  const slideContainer = document.getElementById("slideContainer");
  if (slideContainer) {
    slideContainer.addEventListener("touchstart", (e) => {
      touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });
    slideContainer.addEventListener("touchend", (e) => {
      touchEndX = e.changedTouches[0].screenX;
      handleSwipe();
    }, { passive: true });
  }

  function handleSwipe() {
    const swipeDistance = touchEndX - touchStartX;
    if (swipeDistance < -50) {
      nextSlide();
    } else if (swipeDistance > 50) {
      prevSlide();
    }
  }

  window.addEventListener("DOMContentLoaded", () => {
    initPresentation();
  });

// Bridge for parent Next.js page
window.addEventListener('message', function(e) {
  if (e.data && (e.data.type === 'TRIGGER_FIRST_SECTION_FOCUS' || e.data.type === 'OPEN_PRESENTATION')) {
    if (typeof openPresentation === 'function') {
      openPresentation(0);
    }
  }
});
</script>

<script id="smartboardFocusScript">

(function() {
  if (typeof window === 'undefined') return;

  function balanceHeader() {
    try {
      var header = document.querySelector('.header, .fasikul-header');
      if (!header) return;
      var badge = header.querySelector('.badge-grade');
      if (badge && badge.textContent) {
        badge.textContent = badge.textContent.replace(/Din\\s+Kültürü\\s+ve\\s+Ahlak\\s+Bilgisi/gi, 'Din Kültürü').trim();
      }
      var titleBanner = header.querySelector('.title-banner, .unit-banner');
      if (titleBanner && titleBanner.innerHTML.includes('<br')) {
        titleBanner.innerHTML = titleBanner.innerHTML.replace(/<br\\s*[\\/]?>/gi, ' ').trim();
      }
    } catch(e) {}
  }

  function ensureBrandWatermark() {
    try {
      var sheet = document.querySelector('.notebook-sheet, .fasikul-page');
      if (sheet && !sheet.querySelector('.sheet-brand-bar')) {
        var brandBar = document.createElement('div');
        brandBar.className = 'sheet-brand-bar';
        brandBar.innerHTML = '<div class="brand-pill"><span>🕌</span> <strong>DinDersi Atölyesi</strong></div><div class="brand-motto">MEB Müfredatına Tam Uyumlu Özgün Ders Notu</div>';
        sheet.insertBefore(brandBar, sheet.firstChild);
      }
      var footer = document.querySelector('.footer, .fasikul-footer');
      if (footer && !footer.innerHTML.includes('DinDersi Atölyesi')) {
        var firstDiv = footer.querySelector('div');
        if (firstDiv) {
          firstDiv.innerHTML = '🕌 <strong>DinDersi Atölyesi</strong> | MEB Müfredatına Tam Uyumlu';
        }
      }
    } catch(e) {}
  }

  function initSmartboardFocus() {
    balanceHeader();
    ensureBrandWatermark();

    // Query candidate boxes using all known standard classes
    var rawBoxes = Array.from(document.querySelectorAll(
      '.box, section.box, div.box, section[class*="box-"], div[class*="box-"], .card-box, .box-yellow, .box-cyan, .box-pink, .box-green, .box-orange, .box-purple'
    ));

    // Filter to top-level section boxes only (don't select nested inner items or overlay elements)
    var boxes = rawBoxes.filter(function(el) {
      if (el.id === 'sbCardWrap' || el.id === 'sbStage' || (el.closest && el.closest('#smartboardFocusOverlay'))) return false;
      var parentBox = el.parentElement ? el.parentElement.closest('.box, section[class*="box-"], div[class*="box-"], .card-box') : null;
      return !parentBox;
    });

    if (!boxes.length) return;

    var overlay = document.getElementById('smartboardFocusOverlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'smartboardFocusOverlay';
      overlay.innerHTML = \`
        <div class="smartboard-toolbar" onclick="event.stopPropagation()">
          <div class="sb-info">
            <span class="sb-brand-tag">🕌 DinDersi Atölyesi</span>
            <span class="sb-tag">📌 <span id="sbSectionStep">1/4</span></span>
            <strong id="sbSectionName" class="sb-title">Bölüm Detayı</strong>
          </div>
          <div class="sb-controls">
            <div class="sb-btn-group">
              <span class="sb-label">🔍 Yazı Boyutu:</span>
              <button type="button" class="sb-btn" id="sbFontDec" title="Yazıyı Küçült (-)">A-</button>
              <span class="sb-zoom-badge" id="sbZoomLabel">125%</span>
              <button type="button" class="sb-btn" id="sbFontInc" title="Yazıyı Büyüt (+)">A+</button>
              <button type="button" class="sb-btn sb-btn-ghost" id="sbFontReset" title="Sıfırla">100%</button>
            </div>
            <div class="sb-btn-group">
              <button type="button" class="sb-btn" id="sbPrevBtn" title="Önceki Bölüm (Sol Ok)">◀ Önceki</button>
              <button type="button" class="sb-btn" id="sbNextBtn" title="Sonraki Bölüm (Sağ Ok)">Sonraki ▶</button>
            </div>
            <div class="sb-btn-group">
              <button type="button" class="sb-btn sb-btn-fullscreen" id="sbFullscreenBtn" title="Tam Ekran">⛶ Tam Ekran</button>
              <button type="button" class="sb-btn sb-btn-close" id="sbCloseBtn" title="Kapat (ESC)">✕ Kapat</button>
            </div>
          </div>
        </div>
        <div class="smartboard-stage" id="sbStage">
          <div class="smartboard-card-wrap" id="sbCardWrap">
            <div id="sbCardContent"></div>
          </div>
        </div>
      \
</script>
</body>
</html>
